import { type ReactNode, Fragment } from 'react'
import { AsciiTrail } from '@/components/visuals/AsciiTrail'
import { SiteHeader } from '@/components/site/SiteHeader'
import { RowFan } from '@/components/site/RowFan'
import { AutomationRun } from '@/components/site/AutomationRun'
import { PageClose } from '@/components/site/PageClose'
import { TemplatesWall } from '@/components/blocks/TemplatesWall'
import { FaqBlock } from '@/components/blocks/FaqBlock'
import { SiteFooter } from '@/components/blocks/SiteFooter'
import { templatesPageContent, type TemplatesPageContent, templatesSections, type TemplatesSection, type TemplatesBlocks } from '@/lib/pages/templates'
import { cn } from '@/lib/cn'
import { pageSections } from '@/lib/image'
import type { HeaderMenus } from '@/lib/site-header'

// The site's templates page (app/templates): the header, the templates wall as the hero (an h1 filling the window under
// the header), the automation run (a quote over the batch drifting by), what each template brings back
// (pages/TemplatesPage/TemplateCities: a centered head and a row per template, its name 32/36, 44/48 at 768, 64/68 at
// 1024, each row a link whose items fan out in perspective, the row fan), the questions, the close with a White and a quiet
// button, and the footer. `fan` replaces the row fan with your own arrangement of the rows; `content` replaces
// the copy (lib/pages/templates.ts).
export interface TemplatesPageProps {
  content?: TemplatesPageContent
  /** Your own arrangement of the rows in place of the row fan. */
  fan?: ReactNode
  /** Each block's data, pictures included: the wall's `pictures` and the run's `items`. */
  blocks?: TemplatesBlocks
  /** The header menus' content, pictures included (the live card's `picture`, the use cases' `shots`); Acme by default. */
  menus?: HeaderMenus
  /** The sections to show, in order; all of them in the page order by default (leave one out to omit it). */
  sections?: readonly TemplatesSection[]
  className?: string
}

const WRAP = 'mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)'

export function TemplatesPage({ content: c = templatesPageContent, fan, blocks = {}, menus, sections, className }: TemplatesPageProps) {
  const t = c.cities
  const parts: Record<TemplatesSection, ReactNode> = {
    wall: <TemplatesWall hero content={c.wall} pictures={blocks.wall?.pictures} id="templates" />,
    run: <AutomationRun items={blocks.run?.items} id="templates-run" />,
    cities: (
      <section id={t.id} aria-labelledby={`${t.id}-heading`} className="ds-tpl-cities overflow-x-clip pt-(--ds-layout-section)">
        <div className={cn(WRAP, 'grid justify-items-center text-center')}>
          <h2 id={`${t.id}-heading`} className="type-section [text-box:trim-start_cap_alphabetic]">{t.headline}</h2>
          <p className="mt-4 max-w-(--ds-layout-measure) type-body-lg text-pretty text-fg-soft">{t.lead}</p>
        </div>
        <div className="ds-tpl-cities-rows relative">
          {fan ?? <RowFan rows={t.rows.map((r) => ({ key: r.key, name: r.name, href: r.href, cta: r.line, srLabel: `: ${t.status.toLowerCase()}. ${r.line}`, items: r.items }))} />}
        </div>
      </section>
    ),
    faq: (
      <div className={cn(WRAP, 'py-(--ds-layout-section)')}>
        <FaqBlock id={c.faq.id} title={c.faq.headline} body={c.faq.lead} action={c.faq.docs} items={c.faq.items} />
      </div>
    ),
    close: <PageClose id="templates-close" lines={c.close.lines} note={c.close.note} primary={c.close.primary} secondary={c.close.secondary} control={null} />,
  }
  return (
    <div data-ds="templates-page" className={cn('isolate bg-surface text-fg', className)}>
      <AsciiTrail mode="page" />
      <style href="ds-templates-page" precedence="ds">{css}</style>
      <SiteHeader menus={menus} links={c.chrome.header.nav} secondary={c.chrome.header.secondary} cta={c.chrome.header.cta} />
      <main id="main">
        {pageSections(templatesSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}
      </main>
      <SiteFooter columns={c.chrome.footer.columns} legal={c.chrome.footer.legal} />
    </div>
  )
}

export default TemplatesPage

const css = `
.ds-tpl-cities { padding-bottom: calc(var(--ds-layout-section) - var(--ds-space-lg)); }
.ds-tpl-cities-rows { margin-top: var(--ds-space-3xl); }
@media (min-width: 768px) { .ds-tpl-cities-rows { margin-top: calc(var(--ds-space-4xl) + var(--ds-space-sm)); } }
@media (min-width: 1024px) { .ds-tpl-cities { padding-bottom: var(--ds-layout-section); } }
`

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
